      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations made nonequilibrium statistical mechanics quantitatively testable and connected microscopic reversibility to measurable work and entropy production.",
        "attribution": "Evans and collaborators established early fluctuation relations; Jarzynski's equality and Seifert's stochastic thermodynamics supplied influential general formulations. Crooks also made a major contribution, so a three-person limit requires difficult choices.",
        "maturity": "The relations have extensive theoretical and experimental confirmation and now form a durable framework for small systems.",
        "uncertainties": [
          "The discovery spans several related results, making the boundaries of a single prize citation and the allocation of credit uncertain."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory provided an exceptionally powerful, exact framework for critical phenomena and influenced statistical physics and quantum field theory broadly.",
        "attribution": "The credited trio's foundational work established the conformal bootstrap and exact methods for two-dimensional critical systems.",
        "maturity": "The theory has been developed and tested across many critical systems over decades; its mathematical and physical influence is firmly established.",
        "uncertainties": [
          "The discovery is part of a larger intellectual development involving other contributors, which complicates the scope of a concise citation."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum coherence can be protected in principle, turning quantum computing from a fragile conceptual proposal into a physically meaningful architecture.",
        "attribution": "Shor and Steane independently developed landmark quantum codes, while Kitaev's topological approach gave the field a distinct and influential route to fault tolerance.",
        "maturity": "The principles are established and have guided sustained experimental progress, though large-scale fault-tolerant operation remains an engineering challenge.",
        "uncertainties": [
          "The field has many important later contributors, and the proposed trio represents foundational ideas rather than the full experimental achievement."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated lattice systems tractable while retaining essential local quantum dynamics, enabling a broad understanding of correlated materials.",
        "attribution": "Georges, Kotliar, and Vollhardt were central to formulating and establishing the method and its applications.",
        "maturity": "The framework has been thoroughly developed and applied for decades, with extensions that connect it to real materials and experiments.",
        "uncertainties": [
          "The method is an approximation whose strongest justification is in high-dimensional limits; its predictive reach for specific materials depends on implementation and extensions."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "David R. Nelson",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "KTHNY theory identified how topological defects drive two-dimensional melting and predicted the intermediate hexatic phase, a deep result in statistical physics.",
        "attribution": "Nelson and Halperin, with Young's closely connected work, developed the central theory and its quantitative predictions.",
        "maturity": "The framework is mature and has been extensively tested, with experiments finding the predicted phases in diverse two-dimensional systems.",
        "uncertainties": [
          "Melting pathways depend on material-specific interactions, so the theory does not describe every two-dimensional system uniformly."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Joseph D. Bryngelson",
        "José N. Onuchic",
        "Peter G. Wolynes"
      ],
      "assessment": {
        "nobel_worthiness": "Energy landscape theory gave protein folding a physical account in terms of frustration, rugged landscapes, and routes toward native structure, linking concepts from statistical mechanics to biology.",
        "attribution": "Bryngelson, Onuchic, and Wolynes were key architects of the landscape and minimal-frustration framework.",
        "maturity": "The concepts have been influential for decades and are supported by later structural and dynamical studies, although folding remains a complex, active research area.",
        "uncertainties": [
          "The framework's breadth and explanatory power vary across proteins, and its status as a physics discovery versus a wider biophysical synthesis needs careful framing."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Edward Witten",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "The gauge/gravity correspondence revealed a striking relation between quantum field theories and gravitational theories and has become a major conceptual tool across theoretical physics.",
        "attribution": "Maldacena formulated the central correspondence, and Witten developed its field-theoretic interpretation and important consequences.",
        "maturity": "The conjecture is mathematically rich and extensively used, but its physical realization remains indirect and its most compelling settings are not experimentally accessible.",
        "uncertainties": [
          "The correspondence is not experimentally confirmed as a description of our universe.",
          "Polyakov's earlier contributions to string theory and related ideas make the intellectual lineage broader than the two proposed names."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution turned foundational quantum principles into a clear protocol for secure communication and helped establish quantum information as a physical discipline.",
        "attribution": "Bennett and Brassard proposed the influential BB84 protocol, while Ekert introduced an entanglement-based approach that made the link to Bell nonlocality explicit.",
        "maturity": "The principles are well established and have been demonstrated over practical communication links, though secure deployment still depends on device and implementation assumptions.",
        "uncertainties": [
          "The field's progress is cumulative, and a prize citation would need to distinguish foundational protocols from later experimental and engineering advances."
        ]
      }
    }
  ]
